// The agent loop: hands the six bridge tools to Claude and lets it build.
//
//   1. node server/serve-mod.mjs          (terminal 1)
//   2. yarn gulp in the shapez repo       (terminal 2)
//   3. ANTHROPIC_API_KEY=... npm run agent (terminal 3), then start a game
//
// Options: AGENT_EFFORT (default "high"), AGENT_MAX_TURNS (default 40),
// AGENT_GOAL (free-text extra direction for the opening turn).

import Anthropic from "@anthropic-ai/sdk";
import { betaTool } from "@anthropic-ai/sdk/helpers/beta/json-schema";
import { GameBridge } from "../server/bridge-server.mjs";
import { readIntegerEnv } from "../server/env.mjs";
import { TOOLS, createDispatcher } from "../server/tools.mjs";
import { SYSTEM_PROMPT, initialTask } from "./prompt.mjs";

const MODEL = "claude-opus-5";
// Opus 5 guidance is to start at xhigh for agentic work and sweep down; "high"
// is the cheaper starting point for a loop that runs many turns. Worth testing
// both on your own runs.
const EFFORT = process.env.AGENT_EFFORT || "high";
const MAX_TURNS = readIntegerEnv("AGENT_MAX_TURNS", process.env.AGENT_MAX_TURNS, 40);

// Opus 5's safety classifiers can decline a request outright; this re-serves it
// on another model inside the same call instead of returning the refusal.
// Remove both lines to opt out.
const FALLBACK_BETA = "server-side-fallback-2026-07-01";
const FALLBACKS = "default";

/** Trims tool output so a big observation doesn't dominate the transcript log. */
function summarize(value, limit = 220) {
    const text = typeof value === "string" ? value : JSON.stringify(value);
    return text.length > limit ? `${text.slice(0, limit)}…` : text;
}

async function main() {
    if (!process.env.ANTHROPIC_API_KEY) {
        console.log("ANTHROPIC_API_KEY is not set — trying an `ant auth login` profile.");
    }

    const bridge = new GameBridge().start();
    console.log("Waiting for shapez to launch...");
    await bridge.waitForGame();
    // A live socket only means the app is running; the mod connects at boot, so
    // at the main menu there is no game state to act on.
    await bridge.waitForInGame({
        onWait: () => console.log("Connected — now start or load a savegame."),
    });
    console.log("In game.\n");

    // Pause so `run` is the only thing that advances time. Without this the
    // factory keeps running while the model thinks, and its throughput readings
    // reflect wall-clock rather than the window it asked for.
    await bridge.setPaused(true);

    const dispatch = createDispatcher(bridge);
    let toolCalls = 0;

    const tools = TOOLS.map(spec =>
        betaTool({
            name: spec.name,
            description: spec.description,
            inputSchema: spec.input_schema,
            run: async input => {
                toolCalls++;
                console.log(`  → ${spec.name}(${summarize(input, 120)})`);
                const result = await dispatch(spec.name, input);
                console.log(`    ${result?.error ? "✗ " + result.error : summarize(result)}`);
                return JSON.stringify(result);
            },
        })
    );

    const client = new Anthropic();
    const runner = client.beta.messages.toolRunner({
        model: MODEL,
        max_tokens: 16000,
        system: SYSTEM_PROMPT,
        output_config: { effort: EFFORT },
        betas: [FALLBACK_BETA],
        fallbacks: FALLBACKS,
        tools,
        messages: [{ role: "user", content: initialTask(process.env.AGENT_GOAL || "") }],
        max_iterations: MAX_TURNS,
    });

    let turn = 0;
    let last = null;

    for await (const message of runner) {
        last = message;
        turn++;

        // Refusals arrive as a normal 200 with an empty or partial content
        // array, so check before reading content.
        if (message.stop_reason === "refusal") {
            console.log(`\n[refused: ${message.stop_details?.category ?? "unspecified"}]`);
            break;
        }

        for (const block of message.content) {
            if (block.type === "text" && block.text.trim()) {
                console.log(`\n[turn ${turn}] ${block.text.trim()}`);
            }
        }
    }

    console.log(`\n${"─".repeat(60)}`);
    console.log(`Finished after ${turn} turns and ${toolCalls} tool calls.`);
    if (last?.stop_reason === "max_tokens") {
        console.log("Stopped on max_tokens — the last turn was truncated.");
    }
    if (turn >= MAX_TURNS) {
        console.log(`Hit the ${MAX_TURNS}-turn cap; raise AGENT_MAX_TURNS to let it continue.`);
    }

    // Hand the factory back to real time so you can watch it run.
    await bridge.setPaused(false).catch(() => {});

    const final = await bridge.observe({ ascii: true }).catch(() => null);
    if (final) {
        console.log(`\nLevel ${final.level}, goal ${final.goal?.shape} ` +
            `(${final.goal?.delivered}/${final.goal?.required} delivered), ` +
            `${final.entities.length} buildings placed.`);
        if (final.ascii) console.log(`\n${final.ascii.grid}`);
    }

    bridge.stop();
    process.exit(0);
}

main().catch(err => {
    console.error("\nAgent failed:", err.message);
    process.exit(1);
});

// Runs every suite that doesn't need a running game.

import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const HERE = dirname(fileURLToPath(import.meta.url));
const SUITES = [
    ["belt router", "test-router.mjs"],
    ["bridge protocol", "test-protocol.mjs"],
    ["connect / port resolution", "test-connect.mjs"],
    ["agent loop", "test-agent-loop.mjs"],
    ["atomic file writes", "test-atomic-write.mjs"],
    ["environment settings", "test-env.mjs"],
];

let failed = 0;
for (const [label, file] of SUITES) {
    console.log(`\n${"=".repeat(60)}\n  ${label}\n${"=".repeat(60)}`);
    const result = spawnSync(process.execPath, [join(HERE, file)], { stdio: "inherit" });
    if (result.status !== 0) failed++;
}

console.log(`\n${"=".repeat(60)}`);
console.log(failed ? `${failed} of ${SUITES.length} suites FAILED` : `All ${SUITES.length} suites passed`);
process.exit(failed ? 1 : 0);

import assert from "node:assert/strict";
import { readIntegerEnv } from "../server/env.mjs";

let checks = 0;
function check(name, fn) {
    fn();
    checks++;
    console.log(`  ✓ ${name}`);
}

check("uses the default when a setting is absent", () => {
    assert.equal(readIntegerEnv("AGENT_MAX_TURNS", undefined, 40), 40);
    assert.equal(readIntegerEnv("AGENT_MAX_TURNS", "  ", 40), 40);
});

check("accepts trimmed integers within the configured range", () => {
    assert.equal(readIntegerEnv("BRIDGE_PORT", " 8766 ", 8765, { max: 65_535 }), 8766);
    assert.equal(readIntegerEnv("AGENT_MAX_TURNS", "1", 40), 1);
});

for (const rawValue of ["0", "-1", "2.5", "1e3", "NaN", "Infinity", "65536"]) {
    check(`rejects invalid port value ${JSON.stringify(rawValue)}`, () => {
        assert.throws(
            () => readIntegerEnv("BRIDGE_PORT", rawValue, 8765, { max: 65_535 }),
            error => error instanceof Error && error.message.includes("BRIDGE_PORT") && error.message.includes(rawValue),
        );
    });
}

check("rejects integers larger than JavaScript can represent safely", () => {
    assert.throws(
        () => readIntegerEnv("AGENT_MAX_TURNS", "9007199254740992", 40),
        /AGENT_MAX_TURNS must be an integer/,
    );
});

console.log(`\n${checks} environment-setting checks passed`);

// WebSocket server the shapez mod connects out to.
//
// The game runs in a browser and browsers can't listen, so the agent side hosts
// and the game dials in. One game at a time — a second connection replaces the
// first (that's a page reload, not a second player).

import { WebSocketServer } from "ws";
import { readIntegerEnv } from "./env.mjs";

const PORT = readIntegerEnv("BRIDGE_PORT", process.env.BRIDGE_PORT, 8765, { max: 65_535 });
const DEFAULT_TIMEOUT_MS = 30_000;
export const MAX_RUN_SECONDS = 300;

export function validateRunSeconds(seconds) {
    if (typeof seconds !== "number" || !Number.isFinite(seconds) || seconds <= 0 || seconds > MAX_RUN_SECONDS) {
        throw new Error(`seconds must be a finite number greater than 0 and no more than ${MAX_RUN_SECONDS}`);
    }
    return seconds;
}

export class GameBridge {
    constructor({ port = PORT, log = console.log } = {}) {
        this.port = port;
        this.log = log;
        this.socket = null;
        this.nextId = 1;
        /** @type {Map<number, {resolve: Function, reject: Function, timer: any}>} */
        this.pending = new Map();
        /** @type {Set<{resolve: Function, reject: Function, timer: any}>} */
        this.waitingForConnect = new Set();
        this.server = null;
    }

    start() {
        this.server = new WebSocketServer({ port: this.port });
        this.log(`[bridge] listening on ws://127.0.0.1:${this.port}`);

        this.server.on("connection", socket => this.handleConnection(socket));

        return this;
    }

    handleConnection(socket) {
        if (this.socket) {
            this.log("[bridge] replacing previous connection");
            this.failAllPending(new Error("Game connection replaced"));
            this.socket.terminate();
        }
        this.socket = socket;
        this.log("[bridge] game connected");

        const waiters = [...this.waitingForConnect];
        this.waitingForConnect.clear();
        for (const waiter of waiters) {
            clearTimeout(waiter.timer);
            waiter.resolve();
        }

        socket.on("message", raw => this.onMessage(raw));
        socket.on("close", () => {
            // A replaced socket can close after the new connection is already
            // serving RPCs. Its stale close event must not reject those calls.
            if (this.socket !== socket) return;
            this.socket = null;
            this.log("[bridge] game disconnected");
            this.failAllPending(new Error("Game disconnected"));
        });
        socket.on("error", err => this.log("[bridge] socket error:", err.message));
    }

    stop() {
        this.failAllPending(new Error("Bridge stopped"));
        this.failAllConnectWaiters(new Error("Bridge stopped"));
        if (this.socket) this.socket.terminate();
        if (this.server) this.server.close();
    }

    /** Resolves once the game process has connected its socket. */
    waitForGame(timeoutMs = 120_000) {
        if (this.socket) return Promise.resolve();
        return new Promise((resolve, reject) => {
            const waiter = { resolve, reject, timer: null };
            waiter.timer = setTimeout(() => {
                this.waitingForConnect.delete(waiter);
                reject(new Error(`No game connected after ${timeoutMs}ms`));
            }, timeoutMs);
            this.waitingForConnect.add(waiter);
        });
    }

    /**
     * Resolves once a savegame is actually loaded.
     *
     * The mod connects at app boot, so a live socket only means the game is
     * running — at the main menu there is no root and every RPC but `ping`
     * fails. Poll until it reports in-game.
     */
    async waitForInGame({ timeoutMs = 600_000, pollMs = 1000, onWait } = {}) {
        const deadline = Date.now() + timeoutMs;
        await this.waitForGame(timeoutMs);
        let announced = false;

        for (;;) {
            const remainingBeforePing = deadline - Date.now();
            if (remainingBeforePing <= 0) {
                throw new Error(`Still at the main menu after ${Math.round(timeoutMs / 1000)}s`);
            }

            const status = await this.call(
                "ping",
                {},
                Math.min(DEFAULT_TIMEOUT_MS, remainingBeforePing)
            ).catch(() => null);
            if (status?.inGame) return status;

            if (!announced && onWait) {
                onWait();
                announced = true;
            }
            const remaining = deadline - Date.now();
            if (remaining <= 0) {
                throw new Error(`Still at the main menu after ${Math.round(timeoutMs / 1000)}s`);
            }
            await new Promise(resolve => setTimeout(resolve, Math.min(pollMs, remaining)));
        }
    }

    onMessage(raw) {
        let msg;
        try {
            msg = JSON.parse(raw.toString());
        } catch (ex) {
            this.log("[bridge] unparseable message from game");
            return;
        }

        // Unsolicited notifications (e.g. gameStarted) carry no id.
        if (msg.id === undefined) {
            this.log("[bridge] event:", msg.event || msg.type);
            return;
        }

        const entry = this.pending.get(msg.id);
        if (!entry) return;
        this.pending.delete(msg.id);
        clearTimeout(entry.timer);

        if (msg.ok) entry.resolve(msg.result);
        else entry.reject(new Error(msg.error || "Unknown game-side error"));
    }

    failAllPending(error) {
        for (const [, entry] of this.pending) {
            clearTimeout(entry.timer);
            entry.reject(error);
        }
        this.pending.clear();
    }

    failAllConnectWaiters(error) {
        for (const waiter of this.waitingForConnect) {
            clearTimeout(waiter.timer);
            waiter.reject(error);
        }
        this.waitingForConnect.clear();
    }

    /**
     * Sends an RPC request to the game and resolves with its result.
     * `run` can legitimately take a while, so give it a longer timeout.
     */
    call(method, params = {}, timeoutMs = DEFAULT_TIMEOUT_MS) {
        if (!this.socket || this.socket.readyState !== this.socket.OPEN) {
            return Promise.reject(new Error("No game connected"));
        }

        const socket = this.socket;
        const id = this.nextId++;
        return new Promise((resolve, reject) => {
            const timer = setTimeout(() => {
                this.pending.delete(id);
                reject(new Error(`Timed out after ${timeoutMs}ms: ${method}`));
            }, timeoutMs);

            this.pending.set(id, { resolve, reject, timer });
            const failSend = error => {
                if (!error) return;
                const entry = this.pending.get(id);
                if (!entry) return;

                this.pending.delete(id);
                clearTimeout(entry.timer);
                const message = error instanceof Error ? error.message : String(error);
                reject(new Error(`Failed to send ${method}: ${message}`));
            };

            try {
                socket.send(JSON.stringify({ id, method, params }), failSend);
            } catch (error) {
                failSend(error);
            }
        });
    }

    // Convenience wrappers ---------------------------------------------------

    ping() {
        return this.call("ping");
    }
    observe(params = {}) {
        return this.call("observe", params);
    }
    buildings() {
        return this.call("buildings");
    }
    place(params) {
        return this.call("place", params);
    }
    placeMany(entities, atomic = false) {
        return this.call("placeMany", { entities, atomic });
    }
    remove(x, y) {
        return this.call("remove", { x, y });
    }
    connect(params) {
        return this.call("connect", params);
    }
    setPaused(paused) {
        return this.call("setPaused", { paused });
    }
    /** Stepping is synchronous game-side, so allow generous headroom. */
    run(seconds = 10) {
        const validatedSeconds = validateRunSeconds(seconds);
        return this.call(
            "run",
            { seconds: validatedSeconds },
            Math.max(60_000, validatedSeconds * 2000)
        );
    }
}

// Run standalone: node server/bridge-server.mjs
if (import.meta.url === `file://${process.argv[1]?.replace(/\\/g, "/")}`) {
    const bridge = new GameBridge().start();
    process.on("SIGINT", () => {
        bridge.stop();
        process.exit(0);
    });
}

/**
 * Reads an optional integer environment setting with explicit bounds.
 * Empty values preserve the documented default; malformed values fail before
 * a server starts or an agent run consumes them.
 */
export function readIntegerEnv(name, rawValue, defaultValue, { min = 1, max = Number.MAX_SAFE_INTEGER } = {}) {
    const text = rawValue?.trim();
    if (!text) return defaultValue;

    if (!/^\d+$/.test(text)) {
        throw new Error(`${name} must be an integer between ${min} and ${max}; received ${JSON.stringify(rawValue)}`);
    }

    const value = Number(text);
    if (!Number.isSafeInteger(value) || value < min || value > max) {
        throw new Error(`${name} must be an integer between ${min} and ${max}; received ${JSON.stringify(rawValue)}`);
    }
    return value;
}

// Serves mod/ over HTTP so the shapez dev build can load the bridge via
// config.local.js:
//     externalModUrl: "http://localhost:3006/agent-bridge.js"
//
// The mod loader fetches this URL at startup, so restarting the game reloads
// whatever is on disk — no bundling step.
//
// 3006, not 3005: shapez's own browsersync dev server takes 3005
// (gulp/gulpfile.js:137).

import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join, basename } from "node:path";
import { readIntegerEnv } from "./env.mjs";

const PORT = readIntegerEnv("MOD_PORT", process.env.MOD_PORT, 3006, { max: 65_535 });
const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const MOD_DIR = join(ROOT, "mod");

// Modules the mod may inline via `// @inject <name>`. An allowlist rather than
// an arbitrary path: the result is evaluated as code inside the game, so the
// set of things that can end up there stays fixed and reviewable.
const INJECTABLE = {
    "router/belt-router.mjs": join(ROOT, "router", "belt-router.mjs"),
};

/**
 * Inlines allowlisted modules at their `// @inject` markers.
 *
 * The shapez mod loader evaluates a mod as a single script, so it can't import.
 * Stripping the `export` keywords turns the module into plain declarations that
 * are already in scope — which keeps the router a normal, testable ES module on
 * disk instead of a copy pasted into the mod.
 */
export async function buildMod(source) {
    const marker = /^[ \t]*\/\/ @inject (.+)$/gm;
    const replacements = [];

    for (const match of source.matchAll(marker)) {
        const name = match[1].trim();
        const path = INJECTABLE[name];
        if (!path) {
            throw new Error(
                `@inject ${name} is not allowlisted (add it to INJECTABLE in serve-mod.mjs)`
            );
        }
        const module = await readFile(path, "utf8");
        const inlined = module.replace(/^export\s+(const|function|class|let)\s/gm, "$1 ");
        replacements.push([
            match[0],
            `// --- inlined from ${name} ---\n${inlined}\n// --- end ${name} ---`,
        ]);
    }

    let out = source;
    for (const [from, to] of replacements) out = out.replace(from, to);
    return out;
}

const server = createServer(async (req, res) => {
    // basename() keeps a crafted path from escaping mod/.
    const name = basename(new URL(req.url, "http://localhost").pathname) || "agent-bridge.js";

    try {
        const body = await buildMod(await readFile(join(MOD_DIR, name), "utf8"));
        res.writeHead(200, {
            "Content-Type": "application/javascript; charset=utf-8",
            // The game caches nothing across reloads, but proxies might.
            "Cache-Control": "no-store",
            "Access-Control-Allow-Origin": "*",
        });
        res.end(body);
        console.log(`[mod-server] served ${name}`);
    } catch (ex) {
        // A missing file is a 404; a failed @inject is a build error and must
        // not look like one, or the game just reports "mod not found".
        const missing = ex.code === "ENOENT";
        const status = missing ? 404 : 500;
        const message = missing ? `Not found: ${name}` : `Build failed: ${ex.message}`;
        res.writeHead(status, { "Content-Type": "text/plain" });
        res.end(message);
        console.log(`[mod-server] ${status} ${name} — ${message}`);
    }
});

// Only listen when run directly — tests import buildMod from here.
if (import.meta.url === `file://${process.argv[1]?.replace(/\\/g, "/")}`) {
    server.listen(PORT, () => {
        console.log(`[mod-server] http://localhost:${PORT}/agent-bridge.js`);
    });
}
